using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.Serialization;
using System.Runtime.Serialization.Json;

namespace MCPanel.Setup
{
    /// <summary>
    /// Release metadata generated by Build-OnlineInstaller.ps1 and embedded in
    /// the setup executable. Only metadata is embedded, never the application
    /// ZIP or Microsoft redistributables; the pinned hashes bind each release.
    /// </summary>
    [DataContract]
    internal sealed class SetupConfig
    {
        [DataMember(Name = "version")] public string Version { get; set; }
        [DataMember(Name = "packageUrl")] public string PackageUrl { get; set; }
        [DataMember(Name = "packageSha256")] public string PackageSha256 { get; set; }
        [DataMember(Name = "requiredSpaceBytes")] public long RequiredSpaceBytes { get; set; }
        [DataMember(Name = "maximumRelativeLength")] public int MaximumRelativeLength { get; set; }
        [DataMember(Name = "dotNet")] public Prerequisite DotNet { get; set; }
        [DataMember(Name = "visualCpp")] public Prerequisite VisualCpp { get; set; }
        [DataMember(Name = "programFiles")] public List<string> ProgramFiles { get; set; }
        [DataMember(Name = "preservedTopLevelNames")] public List<string> PreservedTopLevelNames { get; set; }
        [DataMember(Name = "preservedAppSettingKeys")] public List<string> PreservedAppSettingKeys { get; set; }
        [DataMember(Name = "urlMigrations")] public List<UrlMigration> UrlMigrations { get; set; }

        public static SetupConfig LoadEmbedded()
        {
            using (var stream = typeof(SetupConfig).Assembly.GetManifestResourceStream("MCPanel.Setup.setup-config.json"))
            {
                if (stream == null)
                {
                    throw new InvalidDataException("安装程序缺少发布配置，请重新下载官方安装程序。");
                }

                return Load(stream);
            }
        }

        public static SetupConfig Load(Stream stream)
        {
            var serializer = new DataContractJsonSerializer(typeof(SetupConfig));
            var config = (SetupConfig)serializer.ReadObject(stream);
            config.ProgramFiles = config.ProgramFiles ?? new List<string>();
            config.PreservedTopLevelNames = config.PreservedTopLevelNames ?? new List<string>();
            config.PreservedAppSettingKeys = config.PreservedAppSettingKeys ?? new List<string>();
            config.UrlMigrations = config.UrlMigrations ?? new List<UrlMigration>();
            if (string.IsNullOrWhiteSpace(config.Version) || config.DotNet == null || config.VisualCpp == null)
            {
                throw new InvalidDataException("安装程序的发布配置不完整。");
            }

            return config;
        }

        public string NormalizeDownloadUrl(string key, string value)
        {
            foreach (var migration in UrlMigrations)
            {
                if (string.Equals(key, migration.Key, StringComparison.OrdinalIgnoreCase) &&
                    string.Equals((value ?? string.Empty).Trim(), migration.PreviousUrl, StringComparison.OrdinalIgnoreCase))
                {
                    return migration.CurrentUrl;
                }
            }

            return value;
        }
    }

    [DataContract]
    internal sealed class Prerequisite
    {
        [DataMember(Name = "name")] public string Name { get; set; }
        [DataMember(Name = "minimumRelease")] public int MinimumRelease { get; set; }
        [DataMember(Name = "minimumVersion")] public string MinimumVersion { get; set; }
        [DataMember(Name = "url")] public string Url { get; set; }
        [DataMember(Name = "sha256")] public string Sha256 { get; set; }
        [DataMember(Name = "arguments")] public string Arguments { get; set; }
    }

    [DataContract]
    internal sealed class UrlMigration
    {
        [DataMember(Name = "Key")] public string Key { get; set; }
        [DataMember(Name = "PreviousUrl")] public string PreviousUrl { get; set; }
        [DataMember(Name = "CurrentUrl")] public string CurrentUrl { get; set; }
    }
}
